"use strict";(self.webpackChunk_711=self.webpackChunk_711||[]).push([[764],{764(e,n,r){r.r(n),r.d(n,{default:()=>s}),r.dn(s);var a=r(540);function s(){return a.createElement("div",{className:"markdown",dangerouslySetInnerHTML:{__html:'<style>\n.markdown h1, .markdown h2, .markdown h3 {\n    margin: 0;\n}\n</style>\n\n<p>At the border of San Francisco&#39;s Districts 7 and 11, Ingleside is the\nneighborhood we lovingly call home.</p>\n<p>Volunteer with us to build a stronger Ingleside for everyone.</p>\n<p>Follow us on Instagram: <a href="https://instagram.com/711.ingleside">711.ingleside</a></p>\n<hr>\n<h1>Ingleside Trash Pickup</h1>\n<h2>Every Saturday, 11:00am @ <a href="https://maps.app.goo.gl/YPnqurSzgpB4VcxC6">Ocean Ale House</a></h2>\n<p>Since 2023, the Ingleside trash pickup has been happening every Saturday at 11am\nsharp, rain or shine. Meet us in front of Ocean Ale House for an hour of trash\ncollection, followed by lunch and merriment. Trash bags, grabbers, rings, safety\nvests, and gloves are all provided. Sponsored by:</p>\n<ul>\n<li><a href="https://civicjoyfund.org/projects/clean-up-the-city">Civic Joy Fund</a></li>\n<li><a href="https://cleanupthecity.org/">Clean Up The City</a></li>\n<li><a href="https://refuserefusesf.org/">Refuse Refuse SF</a></li>\n<li><a href="https://sfpublicworks.org/get_involved/adopt-street-program">SF Public Works: Adopt-A-Street</a></li>\n</ul>\n<hr>\n<h1><a href="/workshops/">Ingleside Workshops</a></h1>\n<p>Free skill-sharing workshops led by neigborhood volunteers. Learn skills through\nhands-on activities, meet your neighbors, and win raffle prizes.</p>\n<p><a href="/workshops/">Click here to learn more and sign up!</a></p>\n<p>Presented in partnership with:</p>\n<ul>\n<li><a href="https://civicjoyfund.org/">Civic Joy Fund</a></li>\n<li><a href="https://oaacbd.org/">Ocean Avenue Association</a></li>\n</ul>\n'}})}}}]);
